package com.artforyou.store.controller;
import com.artforyou.store.entity.Product; import com.artforyou.store.repository.*; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class CatalogueController {
 private final CollectionRepository collections; private final ProductRepository products; private final ObjectMapper mapper;
 public CatalogueController(CollectionRepository c,ProductRepository p,ObjectMapper m){collections=c;products=p;mapper=m;}
 @GetMapping("/collections") public List<Map<String,Object>> collections(){return collections.findByActiveTrueOrderBySortOrderAsc().stream().map(c->{Map<String,Object> m=new LinkedHashMap<>();m.put("slug",c.getSlug());m.put("title",c.getTitle());m.put("categories",List.of());m.put("imagePath",c.getImagePath());m.put("description",c.getDescription());return m;}).toList();}
 @GetMapping("/products") public List<Map<String,Object>> products(@RequestParam(required=false) String collection,@RequestParam(required=false) String category){Set<String> activeSlugs=collections.findByActiveTrueOrderBySortOrderAsc().stream().map(c->c.getSlug()).collect(java.util.stream.Collectors.toSet());List<Product> rows;if(collection!=null&&!collection.isBlank()){if(!activeSlugs.contains(collection))return List.of();rows=products.findByActiveTrueAndCollectionOrderBySortOrderAscIdAsc(collection);}else if(category!=null&&!category.isBlank())rows=products.findByActiveTrueAndCategoryOrderBySortOrderAscIdAsc(category);else rows=products.findByActiveTrueOrderBySortOrderAscIdAsc();return rows.stream().filter(p->activeSlugs.contains(p.getCollection())).map(p->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("collection",p.getCollection());m.put("category",p.getCategory());m.put("name",p.getName());m.put("price",p.getPrice());m.put("discountPercentage",discountFor(p));try{m.put("images",mapper.readValue(p.getImages(),List.class));}catch(Exception e){m.put("images",List.of());}m.put("description",p.getDescription());return m;}).toList();}
 private int discountFor(Product p){String slug=(p.getCollection()==null?"":p.getCollection()).toLowerCase();String name=(p.getName()==null?"":p.getName()).toLowerCase().replaceAll("[^a-z]","");String category=(p.getCategory()==null?"":p.getCategory()).toLowerCase().replaceAll("[^a-z]","");if(slug.equals("weddingdecor")&&(name.contains("kudakalu")||name.contains("kobbaribondam")||category.contains("kudakalu")||category.contains("kobbaribondam")))return 0;return p.getDiscountPercentage();}
}
